#include <vector>

using namespace std;

class Solution {
public:
    int numSubarrayBoundedMax(vector<int>& nums, int left, int right) {
        return count(nums, right) - count(nums, left - 1);
    }

    int count(vector<int>& nums, int bound) {
        int sum = 0, cur = 0;
        for (int num : nums) {
            cur = (num <= bound) ? cur + 1 : 0;
            sum += cur;
        }
        return sum;
    }
};
